import{_ as d,o as a,c as r,a3 as n}from"./chunks/framework.bvEHUNtb.js";const g=JSON.parse('{"title":"体用生克篇之五：观物洞玄歌","description":"从歌诀、起卦到屋宅与器物，练习将体用之理落在具体情境。","frontmatter":{"title":"体用生克篇之五：观物洞玄歌","description":"从歌诀、起卦到屋宅与器物，练习将体用之理落在具体情境。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md","lastUpdated":1786982540000}'),o={name:"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md"};function s(l,t,p,e,i,h){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占" tabindex="-1">【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占 <a class="header-anchor" href="#【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占" aria-label="Permalink to &quot;【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占&quot;">​</a></h1><blockquote><p>本篇是体用生克篇的收官。从歌诀到案例到器物，将前四篇的理论落地到最具体的生活场景。</p></blockquote><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="观物洞玄歌" tabindex="-1">观物洞玄歌 <a class="header-anchor" href="#观物洞玄歌" aria-label="Permalink to &quot;观物洞玄歌&quot;">​</a></h3><p>洞玄歌者，洞达玄妙之说也。此歌多为占宅气而发。昔牛思晦尝入人家，知其吉凶先兆，盖此术云。是故家之兴衰必有祯祥妖孽之谶，识者鉴之，不识者昧之。故此歌发其蕴奥，皆理之必然者，切勿以浅近目之也。世问万事无非数，理在其中，吉凶悔吝有其机，祸福可先知。其五行，金、木、水、火、土，生克先为主；青、黄、赤、黑、白五形辨，察要分明。</p><p>人家吉凶何堪见？只向玄中判。<br> 入门辨察见闻时，于此察兴衰。<br> 若还宅气如春意，家室生和气。<br> 若然冷落似秋时，从此渐衰微。<br> 自然馨香如兰室，福至无虚日。<br> 鸡豚猫犬秽熏猩，贫病至相侵。<br> 男妆女饰皆齐整，此去门风盛。<br> 家人垢面与蓬头，定见有悲忧。<br> 鬼啼妇叹情怀悄，祸害道阴小。<br> 老人无故泣双垂，不日见愁悲。<br> 门前墙壁缺，家道中渐歇。<br> 溜漕水势向门流，财帛永难收。<br> 忽然屋上生奇草，益荫人家好。<br> 门户幽爽绝尘埃，必定出高才。<br> 偶悬破履当门户，必有奴欺主。<br> 常常破碎在边门，断不利家君。<br> 遮门临井桃花艳，内有风情染。<br> 屋前屋后有高桐，离别主人翁。<br> 井边倘种高梨树，长有离乡土。<br> 祠堂神主忽焚香，火厄恐相招。<br> 檐前瓦片当门堕，诸事愁崩破。<br> 若施破碗厕坑中，从此见贫穷。<br> 白昼不宜灯在地，死者还相继。<br> 公然鼠向日中来，不日耗资财。<br> 牝鸡司晨鸣咿啼，人眷有灾厄。<br> 清晨鹊噪连声继，远行人将至。<br> 蟒蛇偶尔入人家，人病见妖邪。<br> 雀群争遂当门盛，口舌纷纷定。<br> 偶然鹏鸟叫当门，人口有灾逢。<br> 入门若见有群羊，家主病瘟黄。<br> 舟船若安在平地，虽稳成淹滞。<br> 他家树阴过墙来，多得横来财。<br> 阶前石砌多残折，成事多衰灭。<br> 入门茶果应声来，中馈主冢财。<br> 三餐时候炊烟早，家道渐基好。<br> 连宵宿火不成时，人散与财离。<br> 千门万户难详备，理在吾心地。<br> 斯文引路发先天，深奥入玄玄。</p><p>此《洞玄歌》与《灵应》，同出而小异。彼篇多为占卜而诀，盖占卜之际，随所出所见，以为克应之兆。此歌则不特为占卜之事，一时而入人家，有此事，必有此理。盖多寓观察之宋也。然有数端，人家可得警戒而趋避之，或可转祸为福。偶不知所因而宥于数中，俾吾见之，则善恶不逃乎明鉴矣。</p><h3 id="起卦加数例" tabindex="-1">起卦加数例 <a class="header-anchor" href="#起卦加数例" aria-label="Permalink to &quot;起卦加数例&quot;">​</a></h3><p>寅年十二月初一日午时，有数家起造，俱在邻市之间。有三家以此年月日时求占于先生，若同一卦，则吉凶莫辨矣。先生以各姓而加数，遂断之而皆验。盖三家求占，有田姓者，王姓者，韩姓者。若寅年三数、十二与一，共十六，加王姓四画，得二十数，去八一十六，得四，震为上卦；又加午时，七数，总二十七数，去三八二十四，得三，离为下卦。二十七中去四六二十四，余三为初爻，得丰变震，互见兑、巽。其田姓加以田字六画，得水风井，变升，互见离、兑；其韩姓加入二十一画之数，得益变中孚，互见艮、坤。乃以各家之姓起数，随各家之卦断之也。不特起屋之年月日时加姓也，凡冠婚及葬事皆加一姓可矣。若婚姻，则男女大事，必加二姓可也。极北之人无姓，亦必有名，不辨其字，则数声音。又无名，则随所寓也。</p><h3 id="屋宅之占诀" tabindex="-1">屋宅之占诀 <a class="header-anchor" href="#屋宅之占诀" aria-label="Permalink to &quot;屋宅之占诀&quot;">​</a></h3><p>寅年十二月初一日午时起屋者，其家田姓，其占水风井，变地风升，互见离、兑，巽木为体，用卦坎水生也，虽兑金克木，得有离火，火虽无气，终是制金。然有兑金，酉年月日，亦当有损失之忧。亥子水年月日，当有进益，或得水边之财，坎生体巽也。寅卯年当大快意，比和之气也。但家必多口舌之聒，亦为兑也。木体近春。喜逢坎水，此居必能发旺。二十九年后，此屋当毁。盖二十九年者，全卦之成数也。若非有兑在中，虽再见二十九年，屋当无恙也。</p><p>同时王姓家起造，得雷火丰，变震，互见兑、巽。震木为体，离为用卦。兑为体之互，克体亦切。虽得离火制兑金，亦不纯美。用火泄体之气，破耗资财。每遇火年月日，主见此事，或因妇人而有损失。家中亦多女子是非。亥子寅卯之年月，却主进益田财。盖震木为体，虽不见坎，终是利水年。生体之气，不见震巽，亦逢寅、卯，为体卦得局之时也。凡有震有巽，寅卯与木之气运年月，此居必大得意。亦主得长子之力，变重震也。二十二年复为火所焚。</p><p>韩姓之居，得益变中孚。巽体，互见艮、坤，变兑克本。此居必有官讼，见于酉年月日。申酉年连见病患，所喜用卦其震与巽体比和，当见寅卯年月后。申酉年后凶。三十一年之后，遇申酉年，此居当毁。若非有兑，或有一坎，再三十一年，此居亦无恙也。</p><h3 id="器物占" tabindex="-1">器物占 <a class="header-anchor" href="#器物占" aria-label="Permalink to &quot;器物占&quot;">​</a></h3><p>大抵占器物，并不喜见兑卦，盖兑为毁折也。若坎为体，则见兑无伤。干卦为体亦无害。其余卦体，逢兑不久即破。木之器物，或震巽为体，见兑为用，必不禁耐用矣。破器之日，必申酉与占卜之年月日也。又畜养之物，又不宜干、兑克体。种植之物，干、兑克体，必不成，即成，亦有斧戕之厄。种植之物，宜见坎也。</p><p>又凡见器物，欲知其成毁，亦看卦体，无克者则久长。体逢克则不久，视其器物之气数，可久者，以全卦之年数断之；不可久者，以月数断之；至速者，以日数断之也。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>祯祥妖孽</td><td>zhēn xiáng yāo niè</td><td>吉祥之兆（祯祥）与凶恶之兆（妖孽）</td></tr><tr><td>谶</td><td>chèn</td><td>预兆，应验的预言</td></tr><tr><td>蕴奥</td><td>yùn ào</td><td>深藏的奥义</td></tr><tr><td>豚</td><td>tún</td><td>猪</td></tr><tr><td>秽熏猩</td><td>huì xūn xīng</td><td>臭气熏天，猩：腥臭之气</td></tr><tr><td>垢面蓬头</td><td>gòu</td><td>脏脸蓬乱头发，形容邋遢不整</td></tr><tr><td>情怀悄</td><td>qiǎo</td><td>悄：忧愁，情怀悄：心情悲愁</td></tr><tr><td>溜漕</td><td>liù cáo</td><td>屋檐排水槽</td></tr><tr><td>破履</td><td>pò lǚ</td><td>破旧的鞋子</td></tr><tr><td>牝鸡司晨</td><td>pìn jī sī chén</td><td>母鸡报晓，喻阴盛阳衰，家道失序</td></tr><tr><td>鹏鸟</td><td>péng niǎo</td><td>此处指鸱鸮（猫头鹰）一类不祥之鸟</td></tr><tr><td>瘟黄</td><td>wēn huáng</td><td>瘟病，黄疸，泛指重病</td></tr><tr><td>淹滞</td><td>yān zhì</td><td>停滞不前，事业受阻</td></tr><tr><td>中馈</td><td>zhōng kuì</td><td>主持家务的女主人</td></tr><tr><td>冢财</td><td>zhǒng cái</td><td>主财，掌管财务</td></tr><tr><td>宥于数中</td><td>yòu</td><td>被数所困，宥：宽容，此处引申为受困</td></tr><tr><td>俾</td><td>bǐ</td><td>使，令</td></tr><tr><td>聒</td><td>guō</td><td>嘈杂，口舌之聒：话多嘈杂</td></tr><tr><td>斧戕</td><td>fǔ qiāng</td><td>被斧砍伤，戕：伤害</td></tr><tr><td>冠婚</td><td>guān hūn</td><td>冠礼与婚礼，人生大事</td></tr><tr><td>全卦之成数</td><td>—</td><td>全卦各爻五行生成数之总和，用于推算年限</td></tr><tr><td>体卦得局</td><td>—</td><td>体卦所属五行当令得势，即旺相之时</td></tr></tbody></table><hr><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><h3 id="观物洞玄歌-1" tabindex="-1">观物洞玄歌 <a class="header-anchor" href="#观物洞玄歌-1" aria-label="Permalink to &quot;观物洞玄歌&quot;">​</a></h3><p>《洞玄歌》，是洞达玄妙之说。这首歌多为观察宅气而作。从前牛思晦曾进入别人家中，就能预知吉凶先兆，用的正是这套方法。所以一家的兴衰，必然有吉祥或妖孽的征兆，识者能鉴别，不识者则昏昧不知。这首歌发其深藏的奥义，所说的都是必然之理，切勿以为浅显而轻视。世间万事无非数，理在其中，吉凶悔吝各有其机，祸福可以预先知晓。五行金木水火土，生克为主；青黄赤黑白五色辨察，要分明。</p><p><strong>逐句译文</strong>：</p><blockquote><p>人家吉凶何堪见？只向玄中判。<br> 入门辨察见闻时，于此察兴衰。</p></blockquote><p>一家的吉凶从哪里看？只在玄妙之中判断。进门时辨察所见所闻，由此察知兴衰。</p><blockquote><p>若还宅气如春意，家室生和气。<br> 若然冷落似秋时，从此渐衰微。</p></blockquote><p>若家中气息如春天般生机勃勃，家室和气兴旺。若冷落萧条如秋天，从此渐渐衰微。</p><blockquote><p>自然馨香如兰室，福至无虚日。<br> 鸡豚猫犬秽熏猩，贫病至相侵。</p></blockquote><p>室内自然清香如兰，福气日日不断。禽畜臭气熏天，贫病相继侵来。</p><blockquote><p>男妆女饰皆齐整，此去门风盛。<br> 家人垢面与蓬头，定见有悲忧。</p></blockquote><p>家人衣着整洁，门风兴盛。家人邋遢蓬头，必有悲忧。</p><blockquote><p>鬼啼妇叹情怀悄，祸害道阴小。<br> 老人无故泣双垂，不日见愁悲。</p></blockquote><p>家中哭声叹息不断，暗中有祸害。老人无故流泪，不日见愁悲。</p><blockquote><p>门前墙壁缺，家道中渐歇。<br> 溜漕水势向门流，财帛永难收。</p></blockquote><p>门前墙壁残缺，家道渐渐衰歇。屋檐水往门内流，财帛永难聚积。</p><blockquote><p>忽然屋上生奇草，益荫人家好。<br> 门户幽爽绝尘埃，必定出高才。</p></blockquote><p>屋顶忽然长出奇异草木，荫益人家。门户清幽无尘，必出高才。</p><blockquote><p>偶悬破履当门户，必有奴欺主。<br> 常常破碎在边门，断不利家君。</p></blockquote><p>破鞋挂在门口，必有下人欺主。边门常有破碎之物，不利家主。</p><blockquote><p>遮门临井桃花艳，内有风情染。<br> 屋前屋后有高桐，离别主人翁。</p></blockquote><p>井边桃花遮门而艳，家中有风流之事。前后种高大梧桐，主人离别。</p><blockquote><p>井边倘种高梨树，长有离乡土。<br> 祠堂神主忽焚香，火厄恐相招。</p></blockquote><p>井旁种梨树，长有离乡之象（梨→离）。祠堂神位忽然自燃，恐有火厄。</p><blockquote><p>檐前瓦片当门堕，诸事愁崩破。<br> 若施破碗厕坑中，从此见贫穷。</p></blockquote><p>瓦片落在门口，诸事崩破。破碗置于厕所，从此贫穷。</p><blockquote><p>白昼不宜灯在地，死者还相继。<br> 公然鼠向日中来，不日耗资财。</p></blockquote><p>白天灯放地上，死者相继。老鼠白天公然出来，不日耗散财物。</p><blockquote><p>牝鸡司晨鸣咿啼，人眷有灾厄。<br> 清晨鹊噪连声继，远行人将至。</p></blockquote><p>母鸡报晓，家眷有灾厄。清晨喜鹊连续叫，远行之人将归。</p><blockquote><p>蟒蛇偶尔入人家，人病见妖邪。<br> 雀群争遂当门盛，口舌纷纷定。</p></blockquote><p>蛇进入屋内，人病有妖邪。麻雀群聚门前争斗，口舌纷纷必至。</p><blockquote><p>偶然鹏鸟叫当门，人口有灾逢。<br> 入门若见有群羊，家主病瘟黄。</p></blockquote><p>不祥之鸟在门口叫，人口有灾。进门见一群羊，家主病重。</p><blockquote><p>舟船若安在平地，虽稳成淹滞。<br> 他家树阴过墙来，多得横来财。</p></blockquote><p>船放在陆地上，虽稳却停滞不前。邻家树荫越墙而来，多得意外横财。</p><blockquote><p>阶前石砌多残折，成事多衰灭。<br> 入门茶果应声来，中馈主冢财。</p></blockquote><p>台阶石砌残破，成事多衰灭。进门立即有茶果招待，女主人善于掌财。</p><blockquote><p>三餐时候炊烟早，家道渐基好。<br> 连宵宿火不成时，人散与财离。</p></blockquote><p>每日炊烟按时升起，家道渐好。夜夜灶火熄灭，人散财离。</p><blockquote><p>千门万户难详备，理在吾心地。<br> 斯文引路发先天，深奥入玄玄。</p></blockquote><p>万家万户难以穷尽列举，理在心中。这些文字只是引路，真正的先天之理，深奥无穷。</p><p><strong>歌后小结</strong>（原文）：<br> 此《洞玄歌》与《灵应》，同出而小异。彼篇多为占卜而诀，盖占卜之际，随所出所见，以为克应之兆。此歌则不特为占卜之事，一时而入人家，有此事，必有此理。盖多寓观察之意也。然有数端，人家可得警戒而趋避之，或可转祸为福。偶不知所因而宥于数中，俾吾见之，则善恶不逃乎明鉴矣。</p><p>译：《洞玄歌》与《三要灵应》同源而略有不同。《灵应》多为占卜时的克应之诀，是占卜之际随所见所闻取象。此歌则不只用于占卜，而是平时进入人家，有此现象，必有此道理——更多寓含日常观察之意。其中有若干条，人家可以警戒趋避，或可转祸为福。若不知原因而困于数中，让我看见，则善恶不逃于明鉴之下。</p><h3 id="起卦加数例-1" tabindex="-1">起卦加数例 <a class="header-anchor" href="#起卦加数例-1" aria-label="Permalink to &quot;起卦加数例&quot;">​</a></h3><p>寅年十二月初一日午时，有数家同时起造，都在邻近的市镇。有三家以同一年月日时来求占，若用同一卦则吉凶无从分辨。先生以各家姓氏笔画加入总数，分别起卦，断之皆验。</p><p>三家姓氏：田姓、王姓、韩姓。</p><p><strong>王姓起卦过程</strong>（原文详述）：</p><ul><li>寅年3 + 十二月12 + 初一1 = 16，加王姓4画 = 20</li><li>20 ÷ 8 = 2余<strong>4</strong> → 第四卦 → <strong>震</strong>为上卦</li><li>20 + 午时7 = 27</li><li>27 ÷ 8 = 3余<strong>3</strong> → 第三卦 → <strong>离</strong>为下卦</li><li>27 ÷ 6 = 4余<strong>3</strong> → 第<strong>三</strong>爻动</li><li>本卦：<strong>雷火丰</strong>，三爻动，变卦：<strong>重震</strong>，互见兑·巽</li></ul><p><strong>田姓</strong>（田=6画）：</p><ul><li>16 + 6 = 22，22 ÷ 8 余6 → 坎；22 + 7 = 29，29 ÷ 8 余5 → 巽；29 ÷ 6 余5 → 五爻动</li><li>本卦：<strong>水风井</strong>，变卦：<strong>地风升</strong>，互见离·兑</li></ul><p><strong>韩姓</strong>（韩=21画，繁体）：</p><ul><li>16 + 21 = 37，37 ÷ 8 余5 → 巽；37 + 7 = 44，44 ÷ 8 余4 → 震；44 ÷ 6 余2 → 二爻动</li><li>本卦：<strong>风雷益</strong>，变卦：<strong>风泽中孚</strong>，互见艮·坤</li></ul><p><strong>推广原则</strong>：</p><ul><li>冠礼·葬事 → 加<strong>一姓</strong></li><li>婚姻 → 加<strong>二姓</strong>（男女各一）</li><li>无姓有名 → 数名字笔画</li><li>无名 → 数声音音节数</li></ul><h3 id="屋宅之占诀-1" tabindex="-1">屋宅之占诀 <a class="header-anchor" href="#屋宅之占诀-1" aria-label="Permalink to &quot;屋宅之占诀&quot;">​</a></h3><p><strong>田姓·水风井变地风升</strong></p><p>原文：巽木为体，用卦坎水生也，虽兑金克木，得有离火，火虽无气，终是制金。然有兑金，酉年月日，亦当有损失之忧。亥子水年月日，当有进益，或得水边之财，坎生体巽也。寅卯年当大快意，比和之气也。但家必多口舌之聒，亦为兑也。木体近春。喜逢坎水，此居必能发旺。二十九年后，此屋当毁。盖二十九年者，全卦之成数也。若非有兑在中，虽再见二十九年，屋当无恙也。</p><table tabindex="0"><thead><tr><th>项目</th><th>卦象</th><th>五行</th><th>生克</th><th>断语</th></tr></thead><tbody><tr><td>体卦</td><td>巽（下卦·静）</td><td>木</td><td>—</td><td>体为木</td></tr><tr><td>用卦</td><td>坎（上卦·动）</td><td>水</td><td>水生木 ✅</td><td>用生体，吉</td></tr><tr><td>互卦上</td><td>离</td><td>火</td><td>火泄水·制兑金</td><td>离制兑，解克</td></tr><tr><td>互卦下</td><td>兑</td><td>金</td><td>金克木 ⚠️</td><td>克体，有损</td></tr><tr><td>变卦</td><td>地风升（坤上巽下）</td><td>土·木</td><td>坤土克坎水</td><td>用气被削</td></tr></tbody></table><p>吉凶时间节点：</p><ul><li><strong>酉年月日</strong>（金旺）→ 兑金克巽木 → 损失之忧</li><li><strong>亥子年月日</strong>（水旺）→ 坎水生巽木 → 进益，水边之财</li><li><strong>寅卯年月日</strong>（木旺）→ 比和 → 大快意</li><li><strong>终结年限</strong>：二十九年后此屋当毁（全卦成数）；若无兑在互，再二十九年亦无恙</li></ul><p><strong>王姓·雷火丰变重震</strong></p><p>原文：震木为体，离为用卦。兑为体之互，克体亦切。虽得离火制兑金，亦不纯美。用火泄体之气，破耗资财。每遇火年月日，主见此事，或因妇人而有损失。家中亦多女子是非。亥子寅卯之年月，却主进益田财。盖震木为体，虽不见坎，终是利水年。生体之气，不见震巽，亦逢寅、卯，为体卦得局之时也。凡有震有巽，寅卯与木之气运年月，此居必大得意。亦主得长子之力，变重震也。二十二年复为火所焚。</p><table tabindex="0"><thead><tr><th>项目</th><th>卦象</th><th>五行</th><th>生克</th><th>断语</th></tr></thead><tbody><tr><td>体卦</td><td>震（下卦·静）</td><td>木</td><td>—</td><td>体为木</td></tr><tr><td>用卦</td><td>离（上卦·动）</td><td>火</td><td>木生火 ⚠️</td><td>体生用，泄气耗财</td></tr><tr><td>互卦上</td><td>兑</td><td>金</td><td>金克木 ⚠️</td><td>克体，切近</td></tr><tr><td>互卦下</td><td>巽</td><td>木</td><td>木比和 ✅</td><td>助体</td></tr><tr><td>变卦</td><td>重震</td><td>木</td><td>比和 ✅</td><td>助体，长子之力</td></tr></tbody></table><p>吉凶时间节点：</p><ul><li><strong>火年月日</strong>（火旺）→ 离火泄震木 → 破耗，或因妇人损失（离为中女）</li><li><strong>亥子年月日</strong>（水旺）→ 水生木 → 进益（虽无坎，水年利木体）</li><li><strong>寅卯年月日</strong>（木旺）→ 比和得局 → 大得意</li><li><strong>终结年限</strong>：二十二年复为火所焚</li></ul><p><strong>韩姓·风雷益变风泽中孚</strong></p><p>原文：巽体，互见艮、坤，变兑克本。此居必有官讼，见于酉年月日。申酉年连见病患，所喜用卦其震与巽体比和，当见寅卯年月后。申酉年后凶。三十一年之后，遇申酉年，此居当毁。若非有兑，或有一坎，再三十一年，此居亦无恙也。</p><table tabindex="0"><thead><tr><th>项目</th><th>卦象</th><th>五行</th><th>生克</th><th>断语</th></tr></thead><tbody><tr><td>体卦</td><td>巽（下卦·静）</td><td>木</td><td>—</td><td>体为木</td></tr><tr><td>用卦</td><td>震（上卦·动）</td><td>木</td><td>木比和 ✅</td><td>比和，吉</td></tr><tr><td>互卦上</td><td>艮</td><td>土</td><td>土克水（非直接克木）</td><td>中性</td></tr><tr><td>互卦下</td><td>坤</td><td>土</td><td>同上</td><td>中性</td></tr><tr><td>变卦</td><td>中孚上兑</td><td>金</td><td>金克木 ⚠️</td><td>克体，终局有损</td></tr></tbody></table><p>吉凶时间节点：</p><ul><li><strong>酉年月日</strong>（金旺）→ 变卦兑金克巽木 → 官讼</li><li><strong>申酉年</strong>（金旺）→ 连见病患</li><li><strong>寅卯年月后</strong>（木旺）→ 用震与体巽比和得局 → 吉</li><li><strong>终结年限</strong>：三十一年后遇申酉年此屋当毁；若无兑或有一坎，再三十一年亦无恙</li></ul><h3 id="器物占-1" tabindex="-1">器物占 <a class="header-anchor" href="#器物占-1" aria-label="Permalink to &quot;器物占&quot;">​</a></h3><p>原文：大抵占器物，并不喜见兑卦，盖兑为毁折也。若坎为体，则见兑无伤。干卦为体亦无害。其余卦体，逢兑不久即破。木之器物，或震巽为体，见兑为用，必不禁耐用矣。破器之日，必申酉与占卜之年月日也。又畜养之物，又不宜干、兑克体。种植之物，干、兑克体，必不成，即成，亦有斧戕之厄。种植之物，宜见坎也。</p><p>又凡见器物，欲知其成毁，亦看卦体，无克者则久长。体逢克则不久，视其器物之气数，可久者，以全卦之年数断之；不可久者，以月数断之；至速者，以日数断之也。</p><p><strong>核心规则</strong>：</p><table tabindex="0"><thead><tr><th>情况</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td>兑为用（任何体）</td><td>不久即破</td><td>兑为毁折</td></tr><tr><td>坎为体，见兑</td><td>无伤</td><td>兑金生坎水，反生体</td></tr><tr><td>乾为体，见兑</td><td>无害</td><td>乾兑同金，比和</td></tr><tr><td>震·巽为体，见兑</td><td>必不耐用</td><td>金克木</td></tr><tr><td>畜养之物，乾兑克体</td><td>不宜</td><td>克体则物不安</td></tr><tr><td>种植之物，乾兑克体</td><td>不成，或有斧戕</td><td>金克木，斧为金器</td></tr><tr><td>种植之物，见坎</td><td>宜</td><td>水生木</td></tr></tbody></table><p><strong>寿命三档</strong>：</p><table tabindex="0"><thead><tr><th>体卦状态</th><th>时间单位</th><th>说明</th></tr></thead><tbody><tr><td>无克</td><td><strong>年数</strong></td><td>久长</td></tr><tr><td>有克</td><td><strong>月数</strong></td><td>中等</td></tr><tr><td>克甚</td><td><strong>日数</strong></td><td>极速</td></tr></tbody></table><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、洞玄歌与三要灵应-同源异流" tabindex="-1">一、洞玄歌与三要灵应：同源异流 <a class="header-anchor" href="#一、洞玄歌与三要灵应-同源异流" aria-label="Permalink to &quot;一、洞玄歌与三要灵应：同源异流&quot;">​</a></h3><p>原文已明确说明两者的关系：</p><blockquote><p>「此《洞玄歌》与《灵应》，同出而小异。彼篇多为占卜而诀……此歌则不特为占卜之事，一时而入人家，有此事，必有此理。」</p></blockquote><table tabindex="0"><thead><tr><th></th><th>三要灵应篇</th><th>洞玄歌</th></tr></thead><tbody><tr><td>使用场景</td><td>占卜时，随所见取克应</td><td>日常入户，平时观察</td></tr><tr><td>是否起卦</td><td>需要起卦，克应为辅</td><td>不需要起卦，直接观象</td></tr><tr><td>核心逻辑</td><td>外应印证内卦</td><td>象即结论</td></tr><tr><td>可否趋避</td><td>占后知命</td><td><strong>可警戒趋避，转祸为福</strong></td></tr></tbody></table><p>洞玄歌比三要灵应多了一层重要的意义：<strong>可以趋避</strong>。三要灵应是占卜时的印证，洞玄歌是日常的观察——既然是日常，就有机会在事情发生前采取行动。</p><h3 id="二、洞玄歌的五类象" tabindex="-1">二、洞玄歌的五类象 <a class="header-anchor" href="#二、洞玄歌的五类象" aria-label="Permalink to &quot;二、洞玄歌的五类象&quot;">​</a></h3><p>歌诀中的象，可以归纳为五类，每类的逻辑不同：</p><table tabindex="0"><thead><tr><th>类别</th><th>典型例句</th><th>核心逻辑</th></tr></thead><tbody><tr><td><strong>气息·氛围</strong></td><td>馨香如兰→福至；秽熏猩→贫病</td><td>气场即象，清吉浊凶</td></tr><tr><td><strong>人的状态</strong></td><td>男妆女饰齐整→门风盛；垢面蓬头→悲忧</td><td>人是家道的镜子</td></tr><tr><td><strong>建筑·器物</strong></td><td>墙壁缺→家道歇；瓦片堕门→崩破</td><td>物的完整度即家道完整度</td></tr><tr><td><strong>植物</strong></td><td>梨树井边→离乡；高桐前后→离别</td><td>植物象意（梨=离·桐=离别）</td></tr><tr><td><strong>动物·声音</strong></td><td>鹊噪→远人至；鼠白日出→耗财</td><td>动物行为即天地之象</td></tr></tbody></table><p>其中植物一类最有意思——梨树·桃花·高桐，都不是五行生克的逻辑，而是<strong>谐音与象意</strong>的逻辑（梨=离，桃=逃，桐=同→离别）。这与篇之三「物叶音义」完全一致。</p><h3 id="三、起卦加数-三才思想的落地" tabindex="-1">三、起卦加数：三才思想的落地 <a class="header-anchor" href="#三、起卦加数-三才思想的落地" aria-label="Permalink to &quot;三、起卦加数：三才思想的落地&quot;">​</a></h3><p>加姓氏笔画，解决了「同一时间，不同的人，命运不同」的问题。</p><p>背后的逻辑是三才：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>年月日时  = 天地之数（共同的时间背景）</span></span>
<span class="line"><span>姓名笔画  = 人之数（个体的标识）</span></span>
<span class="line"><span>─────────────────────────</span></span>
<span class="line"><span>两者相加  = 此人此时此地之卦</span></span></code></pre></div><p>推广原则的逻辑也很清晰：</p><ul><li>一件事涉及<strong>一个人</strong> → 加一姓</li><li>婚姻涉及<strong>两个人</strong> → 加二姓</li><li>无姓 → 退而求其次，用名；无名 → 用声音（音节数）</li></ul><p>这是「数必有所寓」的原则——人总有某种可以数的标识，没有姓有名，没有名有声音。</p><h3 id="四、屋宅占-时间预测的完整示范" tabindex="-1">四、屋宅占：时间预测的完整示范 <a class="header-anchor" href="#四、屋宅占-时间预测的完整示范" aria-label="Permalink to &quot;四、屋宅占：时间预测的完整示范&quot;">​</a></h3><p>三家断例是全书时间预测最完整的示范，展示了三个层次的递进：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一层：整体吉凶方向</span></span>
<span class="line"><span>    用生体 → 整体吉（田姓）</span></span>
<span class="line"><span>    用泄体 + 互克体 → 有损（王姓）</span></span>
<span class="line"><span>    用比和 + 变克体 → 终局有损（韩姓）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二层：吉凶时间节点（以五行旺衰定年月）</span></span>
<span class="line"><span>    生体之卦气旺的年月 → 吉应之期</span></span>
<span class="line"><span>    克体之卦气旺的年月 → 凶应之期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三层：终结年限（全卦成数）</span></span>
<span class="line"><span>    田姓 → 29年</span></span>
<span class="line"><span>    王姓 → 22年</span></span>
<span class="line"><span>    韩姓 → 31年</span></span></code></pre></div><p>特别值得注意的是**「制」的逻辑**：</p><p>田姓案例中，互卦有兑金克巽木（体），但同时互卦有离火——「火虽无气，终是制金」。离火克兑金，兑金的克体之力被削弱，所以「虽兑金克木，得有离火，终是制金」。</p><p>这是一个三角制衡：<strong>克体之卦，若被另一卦所克，则克体之力减弱</strong>。这与篇之四「体用论」中「此卦克体，诸卦又有克此卦者，稍解其穷」完全对应。</p><h3 id="五、器物占-兑为毁折的核心应用" tabindex="-1">五、器物占：兑为毁折的核心应用 <a class="header-anchor" href="#五、器物占-兑为毁折的核心应用" aria-label="Permalink to &quot;五、器物占：兑为毁折的核心应用&quot;">​</a></h3><p>器物占的核心只有一句：<strong>大抵占器物，并不喜见兑卦，盖兑为毁折也。</strong></p><p>但有两个例外，逻辑很清晰：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坎为体 + 兑为用：兑金生坎水 → 用生体 → 反吉</span></span>
<span class="line"><span>乾为体 + 兑为用：乾兑同金   → 比和   → 无害</span></span></code></pre></div><p>这两个例外再次印证了<strong>体用关系永远优先于单卦象意</strong>的原则。兑的「毁折」之象，在体用关系改变时，结论完全不同。</p><p>寿命三档的逻辑：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>克的强弱 → 决定时间单位</span></span>
<span class="line"><span>无克 → 年（长久）</span></span>
<span class="line"><span>有克 → 月（中等）</span></span>
<span class="line"><span>克甚 → 日（极速）</span></span></code></pre></div><p>这个原则不只适用于器物，可以推广到一切「事物寿命」的判断。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="洞玄歌-生活本身就是一卦" tabindex="-1">洞玄歌：生活本身就是一卦 <a class="header-anchor" href="#洞玄歌-生活本身就是一卦" aria-label="Permalink to &quot;洞玄歌：生活本身就是一卦&quot;">​</a></h3><p>《洞玄歌》让我感受到：<strong>不需要起卦，生活本身就是一卦</strong>。</p><p>「三餐时候炊烟早，家道渐基好。连宵宿火不成时，人散与财离。」</p><p>炊烟按时升起，是一家人有序生活的象——火在，人在，家在。灶火夜夜熄灭，是家道散乱的象——火息，人散，财离。</p><p>不需要五行，不需要卦，直接感受就能知道。这是三要灵应在日常生活中最朴素的应用——<strong>用心感受，万象皆言</strong>。</p><h3 id="梨树·桃花·高桐-象的语言不只是五行" tabindex="-1">梨树·桃花·高桐：象的语言不只是五行 <a class="header-anchor" href="#梨树·桃花·高桐-象的语言不只是五行" aria-label="Permalink to &quot;梨树·桃花·高桐：象的语言不只是五行&quot;">​</a></h3><p>歌诀里有一类象，不走五行生克的路，走的是<strong>谐音与意象</strong>：</p><ul><li>梨树 → 梨=离 → 离乡</li><li>桃花遮门 → 桃=逃，花=风情 → 风流之事</li><li>高桐前后 → 桐=同→离别（梧桐向来是离别之树）</li></ul><p>这让我感受到：象的语言是多维的。五行生克是一个维度，谐音是一个维度，文化意象是一个维度，直觉感受又是一个维度。</p><p>真正的「心易」，是能在当下感受到哪个维度的象最鲜活，然后用那个维度去解读。</p><h3 id="加姓起卦-每个人都是独特的数" tabindex="-1">加姓起卦：每个人都是独特的数 <a class="header-anchor" href="#加姓起卦-每个人都是独特的数" aria-label="Permalink to &quot;加姓起卦：每个人都是独特的数&quot;">​</a></h3><p>同一个时间，不同的人，命运不同——这不是随机的，是因为每个人携带着自己独特的「数」。</p><p>姓名不只是符号，是一个人在天地之数中的坐标。加入这个坐标，卦就从「这个时间的卦」变成了「这个人在这个时间的卦」。</p><p>这让我想到：每个人都是天地之间一个独特的交叉点——时间是横轴，个体是纵轴，两者相交，才是这个人此刻真实的处境。</p><h3 id="「火虽无气-终是制金」" tabindex="-1">「火虽无气，终是制金」 <a class="header-anchor" href="#「火虽无气-终是制金」" aria-label="Permalink to &quot;「火虽无气，终是制金」&quot;">​</a></h3><p>田姓案例里这句话，是全书最精妙的一句断语之一。</p><p>离火在互卦中，按时令「火虽无气」（非夏月，离不当令），但它依然存在，依然克制着兑金。力量虽弱，但制衡的关系还在。</p><p>这让我感受到：<strong>力量的存在与力量的强弱，是两回事</strong>。弱的力量不等于没有力量。在判断吉凶时，不只看「有没有」，还要看「强不强」——这就是衰旺论的精髓在具体案例中的体现。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>洞玄歌：不起卦的日常观象，气息·人·建筑·植物·动物五类</li><li>洞玄歌可趋避转祸，三要灵应为占卜克应，两者同源异流</li><li>植物象意：梨=离，桃=风情，桐=离别（谐音与文化意象，非五行）</li><li>加姓起卦：年月日时（天地数）+ 姓名笔画（人数）= 个体化之卦</li><li>婚姻加二姓，无姓加名，无名数声音</li><li>屋宅占三层：整体方向 → 吉凶节点（五行旺衰年月）→ 终结年限</li><li>「制」的逻辑：克体之卦被另一卦所克，则克体之力减弱</li><li>器物占：兑为毁折，坎体·乾体例外（体用关系优先于单卦象意）</li><li>寿命三档：无克用年数，有克用月数，克甚用日数</li></ul><p><strong>规律提炼</strong></p><ol><li>洞玄歌是三要灵应的日常版——不起卦，直接观象，且可趋避</li><li>象的语言是多维的：五行生克·谐音·文化意象·直觉感受，各有其用</li><li>加姓起卦体现三才：天地之数（年月日时）+ 人之数（姓名）= 完整之卦</li><li>时间预测三层：方向→节点→年限，层层递进</li><li>「制」的三角制衡：克体之卦被克，克力减弱；生体之卦被克，生力减弱</li><li>体用关系永远优先于单卦象意（兑为毁折，但坎体·乾体例外）</li><li>寿命推算：克的强弱决定时间单位（年·月·日）</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之三「草木·禽兽·杂见观物·物叶音义」→ 洞玄歌：同一套感知逻辑的生活化展开</li><li>篇之四「衰旺论」→ 屋宅占吉凶时间节点：旺年吉，衰年凶，完全对应</li><li>篇之四「体用论·体一用百」→ 器物占：体用关系优先，兑的象意在体用关系下被修正</li><li>篇之一「数理合参」→ 起卦加数例：数（笔画）与理（卦象）的再次结合</li><li>篇之四「体用」中「此卦克体，诸卦又有克此卦者，稍解其穷」→ 田姓「火虽无气，终是制金」：同一原则的案例印证</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-019</strong>：起卦加数例中，王姓计算：3+12+1+4=20，20÷8=2余4→震（先天第四卦）✅；20+7=27，27÷8=3余3→离（先天第三卦）✅；27÷6=4余3→第三爻动✅。田姓：3+12+1+6=22，22÷8=2余6→坎（先天第六卦）✅；22+7=29，29÷8=3余5→巽（先天第五卦）✅；29÷6=4余5→第五爻动✅。韩姓：3+12+1+21=37，37÷8=4余5→巽✅；37+7=44，44÷8=5余4→震✅；44÷6=7余2→第二爻动✅。三家计算逻辑完全一致，先天卦序数（乾一兑二离三震四巽五坎六艮七坤八）确认无误。</p></blockquote><blockquote><p><strong>❓****-020</strong>：屋宅占「全卦之成数」——田姓29年·王姓22年·韩姓31年，这三个数字的具体推算方式原文未详述（只说「全卦之成数也」）。是六爻爻数之和？还是卦中各五行生成数之和？待卷三「年月日时断例」章节核对。</p></blockquote><blockquote><p><strong>❓****-021</strong>：洞玄歌「舟船若安在平地，虽稳成淹滞」——船在陆地上虽然稳，但无法行驶，象征事业停滞。这个象是纯粹的直觉象意（物不在其位则不能发挥功用），还是有五行逻辑（巽为舟，离陆则巽木无水）？两种解读都说得通，存疑备注。</p></blockquote>`,163)])])}const c=d(o,[["render",s]]);export{g as __pageData,c as default};
